head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/**
 * @method
 * @name KRX_PanelToGroupBox
 * @description desc
 * @param {string} objPanel desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.KRX_PanelToGroupBox = function(objPanel) {
    switch (objPanel.className) {
        case "TopCondition_01":
            scwin.KRX_PanelToGroupBox_01(objPanel);
            break;
        case "Description_01":
            scwin.KRX_PanelToGroupBox_02(objPanel);
            break;
    }
};
/**
 * @method
 * @name KRX_PanelToGroupBox_01
 * @description desc
 * @param {string} objPanel desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.KRX_PanelToGroupBox_01 = function(objPanel) {
    var _left_ = objPanel.style.left;
    var _top_ = objPanel.style.top;
    var _width_ = objPanel.style.getStyle("width");

    // Panel의 left와 top 조정 (static position 방식으로, 좌표 0,0로...)
    objPanel.style.left = '0 px';
    objPanel.style.top = '0 px';
    objPanel.style.position = 'static';

    // Panel의 width와 height 조정 (-20씩)
    objPanel.style.setGridWidth((parseInt(objPanel.style.getStyle("width")) - 20) + ' px');
    objPanel.style.setGridHeight((parseInt(objPanel.style.getStyle("height")) - 20) + ' px');

    // Panel 내부 컨트롤의 left와 top 조정 해야하나?

    // Panel 외부를 테이블로 감싼다.(라운드 테이블)
    var strTableHTML_before = '<table border="0" cellspacing="0" cellpadding="0" style="position:absolute;width:' + _width_ + ';left:' + _left_ + ';top:' + _top_ + ';"><tr><td width="10" height="10"><img src="../img/2_img33.gif" width="10" height="10"></td><td height="10" background="../img/2_img34.gif"></td><td width="10" height="10"><img src="../img/2_img35.gif" width="10" height="10"></td></tr><tr><td background="../img/2_img36.gif">&nbsp;</td><td align="center" bgcolor="d9e9fc">';
    var strPanelHTML = objPanel.outerHTML;
    var strTableHTML_after = '</td><td background="../img/2_img37.gif">&nbsp;</td></tr><tr><td width="10" height="10"><img src="../img/2_img38.gif" width="10" height="10"></td><td height="10" background="../img/2_img39.gif"></td><td><img src="../img/2_img40.gif" width="10" height="10"></td></tr></table>';
    objPanel.outerHTML = strTableHTML_before + strPanelHTML + strTableHTML_after;
};
/**
 * @method
 * @name KRX_PanelToGroupBox_02
 * @description desc
 * @param {string} objPanel desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.KRX_PanelToGroupBox_02 = function(objPanel) {
    var _left_ = objPanel.style.left;
    var _top_ = objPanel.style.top;
    var _width_ = objPanel.style.getStyle("width");

    // Panel의 left와 top 조정 (static position 방식으로, 좌표 0,0로...)
    objPanel.style.left = '0 px';
    objPanel.style.top = '0 px';
    objPanel.style.position = 'static';

    // Panel의 width와 height 조정 (width-20, height-12)
    objPanel.style.setGridWidth((parseInt(objPanel.style.getStyle("width")) - 20) + ' px');
    objPanel.style.setGridHeight((parseInt(objPanel.style.getStyle("height")) - 12) + ' px');

    // Panel 내부 컨트롤의 left와 top 조정 해야하나?

    // Panel 외부를 테이블로 감싼다.(라운드 테이블)
    var strTableHTML_before = '<table border="0" cellpadding="0" cellspacing="0" style="position:absolute;width:' + _width_ + ';left:' + _left_ + ';top:' + _top_ + ';"><tr> <td width="10" height="6"><img src="../img/2_img41.gif" width="10" height="6"></td><td height="6" align="center" background="../img/2_img42.gif"></td><td width="10"><img src="../img/2_img43.gif" width="10" height="6"></td></tr><tr> <td background="../img/2_img44.gif"></td><td align="center" bgcolor="eeeeee" class="text_d">';
    var strPanelHTML = objPanel.outerHTML;
    var strTableHTML_after = '</td><td background="../img/2_img45.gif"></td></tr><tr> <td width="10" height="6"><img src="../img/2_img46.gif" width="10" height="6"></td><td background="../img/2_img47.gif"></td><td><img src="../img/2_img48.gif" width="10" height="6"></td></tr></table>';
    objPanel.outerHTML = strTableHTML_before + strPanelHTML + strTableHTML_after;
};
